export function nextGeneration(liveCells: Cell[]): Cell[] {
  return candidates(liveCells).filter((cell) =>
    survivesOrIsBorn(cell, liveCells),
  );
}

function survivesOrIsBorn(cell: Cell, liveCells: Cell[]): boolean {
  const neighbors = countLiveNeighbors(cell, liveCells);
  if (isAlive(cell, liveCells)) return neighbors === 2 || neighbors === 3;
  return neighbors === 3;
}

function candidates(liveCells: Cell[]): Cell[] {
  const seen = new Map<string, Cell>();
  for (const [x, y] of liveCells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const candidate: Cell = [x + dx, y + dy];
        seen.set(key(candidate), candidate);
      }
    }
  }
  return [...seen.values()];
}

function isAlive(cell: Cell, liveCells: Cell[]): boolean {
  return liveCells.some((other) => key(other) === key(cell));
}

function key([x, y]: Cell): string {
  return `${x},${y}`;
}

