export type Cell = [number, number];

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter(
    (cell) => countLiveNeighbors(cell, liveCells) === 3,
  );
}

function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter((other) => isNeighbor(cell, other)).length;
}

function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  const isSameCell = x === otherX && y === otherY;
  const isAdjacent =
    isWithinOneStep(x, otherX) && isWithinOneStep(y, otherY);
  return isAdjacent && !isSameCell;
}

function isWithinOneStep(coordinate: number, other: number): boolean {
  return Math.abs(coordinate - other) <= 1;
}

